def inject_url_defaults(self, endpoint: str, values: dict) -> None:
    """Injects the URL defaults for the given endpoint directly into
    the values dictionary passed.  This is used internally and
    automatically called on URL building.

    .. versionadded:: 0.7
    """
    funcs: t.Iterable[URLDefaultCallable] = self.url_default_functions[None]
    if "." in endpoint:
        bp = endpoint.rsplit(".", 1)[0]
        funcs = chain(funcs, self.url_default_functions[bp])
    for func in funcs:
        func(endpoint, values)

def blueprint(self) -> t.Optional[str]:
    """The name of the current blueprint"""
    if self.url_rule and "." in self.url_rule.endpoint:
        return self.url_rule.endpoint.rsplit(".", 1)[0]
    else:
        return None

def test_blueprint_url_defaults(app, client):
    bp = flask.Blueprint("test", __name__)

    @bp.route("/foo", defaults={"baz": 42})
    def foo(bar, baz):
        return f"{bar}/{baz:d}"

    @bp.route("/bar")
    def bar(bar):
        return str(bar)

    app.register_blueprint(bp, url_prefix="/1", url_defaults={"bar": 23})
    app.register_blueprint(bp, url_prefix="/2", url_defaults={"bar": 19})

    assert client.get("/1/foo").data == b"23/42"
    assert client.get("/2/foo").data == b"19/42"
    assert client.get("/1/bar").data == b"23"
    assert client.get("/2/bar").data == b"19"

